<!-- 시연용 관리자 보조 기능: 백엔드 모듈이 준비되기 전 조작 흐름을 확인합니다. -->
<script setup>
import { computed, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useAuthSession } from "@/stores/auth";

const route = useRoute(); const router = useRouter(); const { setAccessToken } = useAuthSession();
const isCategory = computed(() => route.params.tool === "category");
const categories = ref(["강아지관", "고양이관", "식기·급수관"]);
const categoryName = ref(""); const maintenance = ref(false); const notice = ref("");
function addCategory(){if(!categoryName.value.trim())return;categories.value.push(categoryName.value.trim());categoryName.value="";notice.value="카테고리가 시연 화면에 추가되었습니다.";}
function saveSettings(){notice.value="환경 설정이 시연용 브라우저 상태에 저장되었습니다.";}
function logout(){setAccessToken("");router.push("/login");}
</script>
<template><div class="demo"><aside><b>PAWCAST</b><span>관리자 페이지</span><nav><RouterLink to="/admin/dashboard">대시보드</RouterLink><RouterLink to="/admin/sales">매출 대시보드</RouterLink><RouterLink to="/admin/orders">주문 관리</RouterLink><RouterLink to="/admin/products">상품 관리</RouterLink><RouterLink class="active" to="/admin/category">카테고리 관리</RouterLink><RouterLink to="/admin/members">고객 관리</RouterLink><RouterLink to="/admin/settings">환경 설정</RouterLink></nav><button @click="logout">로그아웃</button></aside><main><header><small>DEMO ADMIN TOOL</small><h1>{{ isCategory ? '카테고리 관리' : '환경 설정' }}</h1><p>시연을 위한 임시 화면입니다. 서버 저장 기능은 연결 전입니다.</p></header><section v-if="isCategory"><h2>상품 카테고리</h2><form @submit.prevent="addCategory"><input v-model="categoryName" placeholder="카테고리 이름" /><button>추가</button></form><ul><li v-for="item in categories" :key="item">{{ item }}</li></ul></section><section v-else><h2>운영 환경</h2><label><input v-model="maintenance" type="checkbox" /> 점검 모드 표시</label><button @click="saveSettings">설정 저장</button></section><p v-if="notice" class="notice">{{ notice }}</p></main></div></template>
<style scoped>.demo{display:grid;grid-template-columns:240px 1fr;min-height:100vh;background:#f7f5f2;color:#3d281b}.demo aside{display:flex;flex-direction:column;gap:8px;background:#fffcf7;border-right:1px solid #eadfd3;padding:30px 18px}.demo aside>b{font-size:26px;color:#875738}.demo aside>span{color:#987e6b;font-size:12px}.demo nav{display:grid;gap:6px;margin-top:22px}.demo a,.demo button{border:0;border-radius:10px;background:transparent;padding:14px;color:#4b3425;font:inherit;font-weight:800;text-align:left;text-decoration:none}.demo a:hover,.demo .active{background:#a66b3f;color:#fff}.demo aside>button{margin-top:auto;border:1px solid #d8bca2;background:#fff}.demo main{padding:48px clamp(24px,6vw,88px)}small{color:#a66838;font-weight:900;letter-spacing:.12em}h1{margin:8px 0}.demo main>header p{color:#917866}.demo section{display:grid;gap:16px;max-width:650px;margin-top:28px;border:1px solid #e8d8ca;border-radius:16px;background:#fff;padding:24px}.demo form{display:flex;gap:8px}.demo input{border:1px solid #dbc8b6;border-radius:9px;padding:12px;font:inherit}.demo section>button,.demo form button{width:max-content;border:1px solid #a66b3f;background:#a66b3f;color:#fff}.demo ul{display:grid;gap:8px;margin:0;padding:0;list-style:none}.demo li{border-bottom:1px solid #f0e5dc;padding:10px 0}.notice{color:#3e7a4b}@media(max-width:850px){.demo{grid-template-columns:1fr}.demo nav{grid-template-columns:repeat(2,1fr)}}</style>
